package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNotSame;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.nio.file.Path;
import java.util.stream.Stream;

import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.TupleQuery;
import org.eclipse.rdf4j.query.TupleQueryResult;
import org.eclipse.rdf4j.repository.RepositoryConnection;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.Arguments;
import org.junit.jupiter.params.provider.MethodSource;

class LmdbNowIdentityTest {

	@TempDir
	Path directory;

	@ParameterizedTest
	@MethodSource("sharedNowQueries")
	void nowPreservesIdentityAcrossAliasesRowsAndNestedOperators(String query, int expectedRows) {
		SailRepository repository = new SailRepository(new LmdbStore(directory.toFile()));
		repository.init();
		try (RepositoryConnection connection = repository.getConnection()) {
			Value now = null;
			int rows = 0;
			try (TupleQueryResult result = connection.prepareTupleQuery(query).evaluate()) {
				while (result.hasNext()) {
					BindingSet bindings = result.next();
					Value first = bindings.getValue("first");
					assertNotNull(first);
					assertSame(first, bindings.getValue("second"));
					assertSame(first, bindings.getValue("alias"));
					if (now != null) {
						assertSame(now, first, "every NOW invocation in a query must share the captured literal");
					}
					now = first;
					rows++;
				}
			}
			assertEquals(expectedRows, rows);
			assertNotNull(now);
			assertTrue(now.stringValue().contains("T"), "the shared dateTime must remain readable after result close");
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void evaluatingTheSameQueryAgainCreatesAnIndependentNowObject() {
		SailRepository repository = new SailRepository(new LmdbStore(directory.toFile()));
		repository.init();
		try (RepositoryConnection connection = repository.getConnection()) {
			TupleQuery query = connection.prepareTupleQuery("SELECT (NOW() AS ?first) (NOW() AS ?second) WHERE {}");
			Value firstEvaluation = queryTime(query);
			Value secondEvaluation = queryTime(query);
			assertNotSame(firstEvaluation, secondEvaluation, "the captured singleton belongs to one evaluation");
			assertTrue(firstEvaluation.stringValue().contains("T"));
			assertTrue(secondEvaluation.stringValue().contains("T"));
		} finally {
			repository.shutDown();
		}
	}

	private static Value queryTime(TupleQuery query) {
		try (TupleQueryResult result = query.evaluate()) {
			assertTrue(result.hasNext());
			BindingSet bindings = result.next();
			Value first = bindings.getValue("first");
			assertNotNull(first);
			assertSame(first, bindings.getValue("second"));
			return first;
		}
	}

	private static Stream<Arguments> sharedNowQueries() {
		return Stream.of(
				Arguments.of("""
						SELECT ?first (NOW() AS ?second) (?first AS ?alias) WHERE { BIND(NOW() AS ?first) }
						""", 1),
				Arguments.of("""
						SELECT ?row ?first ?second ?alias WHERE {
						  VALUES ?row { 1 2 }
						  BIND(NOW() AS ?first)
						  BIND(NOW() AS ?second)
						  BIND(?first AS ?alias)
						}
						""", 2),
				Arguments.of("""
						SELECT ?row ?first ?second ?alias WHERE {
						  { SELECT (NOW() AS ?first) WHERE {} }
						  {
						    { VALUES ?row { 1 2 } BIND(NOW() AS ?second) }
						    UNION
						    { VALUES ?row { 3 } BIND(NOW() AS ?second) }
						  }
						  OPTIONAL { BIND(NOW() AS ?alias) }
						}
						""", 3));
	}
}
